<!doctype html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=mc_h($news?$news['title']:'Noticia no encontrada')?> | Multicredit</title><meta name="description" content="<?=mc_h($news?($news['summary']?:$news['title']):'Noticia no encontrada')?>"><script>tailwind=window.tailwind||{};tailwind.config={theme:{extend:{colors:{'brand-green':'#0B1F3A','brand-green-dark':'#050B14','brand-orange':'#1F4E79'},fontFamily:{sans:['Inter','sans-serif'],display:['Poppins','sans-serif']}}}};</script><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Poppins:wght@500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/noticias.css"></head><body class="mc-site bg-gray-50 text-gray-800 overflow-x-hidden"><?php include'encabezado.php';?><main id="contenido-principal" class="pt-[82px]"><?php if(!$news):?><section class="news-not-found"><i class="far fa-circle-xmark"></i><h1>Noticia no encontrada</h1><p>La publicación no existe, está en borrador o todavía no llegó su fecha de publicación.</p><a href="noticias.php">Volver a noticias</a></section><?php else:$images=(array)($news['images']??[]);$count=count($images);?><article class="news-detail"><header class="news-detail-head"><a href="noticias.php"><i class="fas fa-arrow-left"></i> Todas las noticias</a><div class="news-detail-meta"><span><?=mc_h($news['category'])?></span><time datetime="<?=mc_h($news['date'])?>"><?=mc_h(mc_month_label($news['date']))?></time></div><h1><?=mc_h($news['title'])?></h1><?php if(!empty($news['summary'])):?><p><?=mc_h($news['summary'])?></p><?php endif;?></header><?php if($images):?><div class="fb-gallery fb-gallery-<?=min($count,5)?>" data-gallery><?php foreach($images as$i=>$image):?><button type="button" class="fb-gallery-item" data-index="<?=$i?>" aria-label="Abrir imagen <?=$i+1?> de <?=$count?>"><img src="<?=mc_h($image['path'])?>" alt="<?=mc_h($news['title'])?>, fotografía <?=$i+1?>" <?php if($i===0):?>fetchpriority="high"<?php else:?>loading="lazy" decoding="async"<?php endif;?>><?php if($i===4&&$count>5):?><span class="gallery-more">+<?=$count-5?></span><?php endif;?></button><?php endforeach;?></div><?php endif;?><div class="news-detail-body"><?=mc_nl2br($news['body'])?></div><footer class="news-detail-footer"><span>Publicado por CEPRODEMIC MULTICREDIT</span><a href="contacto.php">Contáctanos <i class="fas fa-arrow-right"></i></a></footer></article><?php endif;?></main><?php if($news&&$images):?><div class="news-lightbox" id="news-lightbox" aria-hidden="true"><button type="button" class="lightbox-close" aria-label="Cerrar">×</button><button type="button" class="lightbox-prev" aria-label="Imagen anterior">‹</button><figure><img alt=""><figcaption></figcaption></figure><button type="button" class="lightbox-next" aria-label="Imagen siguiente">›</button></div><script>window.MC_NEWS_IMAGES=<?=json_encode(array_values(array_map(function($i){return['path'=>$i['path']];},$images)),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;</script><script src="js/noticias.js" defer></script><?php endif;?><?php include'footer.php';?></body></html>
